package com.ecole.gestion_scolaire.registration.controller; import com.ecole.gestion_scolaire.common.dto.PageResponse; import com.ecole.gestion_scolaire.registration.dto.*; import com.ecole.gestion_scolaire.registration.service.StudentEnrollmentService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/enrollments") public class StudentEnrollmentController{private final StudentEnrollmentService service;public StudentEnrollmentController(StudentEnrollmentService s){service=s;}@GetMapping @PreAuthorize("hasAuthority('SCOLARISATION_CONSULTER')") public PageResponse<StudentEnrollmentResponse> byYear(@RequestParam Long schoolYearId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.byYear(schoolYearId,page,size);}@PostMapping("/{id}/change-class") @PreAuthorize("hasAuthority('SCOLARISATION_MODIFIER')") public StudentEnrollmentResponse changeClass(@PathVariable Long id,@Valid @RequestBody ClassChangeRequest r){return service.changeClass(id,r);}}
